-- EmploymentType: FULL_TIME, PART_TIME, CONTRACT, FREELANCE, INTERNSHIP, APPRENTICESHIP, SELF_EMPLOYED
-- IntegrationStatus: PENDING, CONNECTED, DISCONNECTED, ERROR, EXPIRED

